-- ARC · Irene Prats (mes 2): ejercicios nuevos, alta como asesorada, rutina de 4 días y dieta. App gratis por ser asesorada.
alter table public.coach_clients add column if not exists diet jsonb;

insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, unit, sort) values
  ('ARC-108', 'Tríceps', 'Extensión de tríceps en polea con cuerda', 'Tríceps', 'Polea', 'De pie frente a la polea alta con la cuerda, estiras los codos hacia abajo abriendo la cuerda al final y vuelves despacio.', 'Codos pegados al cuerpo, 1 segundo apretando abajo y subida en 2-3 segundos.', '', 840),
  ('ARC-109', 'Tríceps', 'Extensión de tríceps sobre la cabeza en polea', 'Tríceps (porción larga)', 'Polea', 'De espaldas a la polea, con los codos apuntando al frente junto a la cabeza, estiras los brazos hacia delante y arriba.', 'Estira del todo y baja lento notando el estiramiento del tríceps.', '', 841),
  ('ARC-110', 'Glúteo y cadera', 'Hiperextensiones 45º enfoque glúteo', 'Glúteo, lumbar, femoral', 'Banco 45º', 'En el banco de 45º con los pies algo abiertos y girados hacia fuera, bajas el tronco y subes apretando el glúteo hasta alinear el cuerpo.', 'Espalda ligeramente redondeada y sin hiperextender la lumbar arriba.', '', 842),
  ('ARC-111', 'Espalda', 'Pullover en polea alta', 'Dorsal ancho', 'Polea', 'Con los brazos casi estirados y la cadera atrás, llevas la cuerda o barra desde arriba hasta los muslos usando la espalda.', 'Vuelve lento hasta notar el estiramiento del dorsal; los codos no se doblan.', '', 843)
on conflict (id) do nothing;

-- Alta en tu cuenta (sea coach o admin). Se une sola a su cuenta por el correo.
insert into public.coach_clients (coach_id, email, name)
select c.id, 'irepraga_89@hotmail.com', 'Irene'
from (select id from public.profiles where role in ('coach', 'admin')) c
on conflict (coach_id, email) do update set name = excluded.name, updated_at = now();

