-111", "sets": 2, "reps": "10–15", "rir": 1, "rest": 90}, {"id": "ARC-026", "sets": 2, "reps": "12–15", "rir": 0, "rest": 90}, {"id": "ARC-020", "sets": 2, "reps": "12–15 (superserie con el siguiente)", "rir": 1, "rest": 30}, {"id": "ARC-102", "sets": 3, "reps": "10–12", "rir": 1, "rest": 90}]}]$arc$::jsonb, diet = $arc${"train": [{"name": "Pre-entreno (≈6:40, solo días de entreno)", "options": [{"name": "Plátano", "note": "Cómetelo 20-30 min antes de entrenar con un vaso de agua.", "items": [{"n": "Platano", "g": 110, "kcal": 101.2, "f": 0.55, "c": 28.6, "p": 1.1, "note": "1 mediano, con un vaso de agua"}]}, {"name": "Tortitas de arroz con miel", "note": "Reparte la miel sobre las 2 tortitas. 20-30 min antes de entrenar.", "items": [{"n": "Tortitas de arroz/maiz", "g": 20, "kcal": 73, "f": 0.34, "c": 16, "p": 1.5, "note": "2 tortitas"}, {"n": "Miel", "g": 10, "kcal": 30, "f": 0, "c": 7.51, "p": 0.04, "note": "1 cucharadita repartida"}]}, {"name": "Zumo de naranja", "note": "Un vaso grande 20-30 min antes de entrenar.", "items": [{"n": "Zumo de naranja", "g": 220, "kcal": 103.4, "f": 3.52, "c": 22, "p": 5.28, "note": "1 vaso grande, natural o envasado"}]}, {"name": "Dátiles", "note": "3-4 dátiles 20-30 min antes de entrenar, con agua.", "items": [{"n": "Datiles", "g": 35, "kcal": 103.6, "f": 0.17, "c": 23.8, "p": 0.77, "note": "3-4 dátiles"}]}]}, {"name": "Desayuno (≈8:00, al volver de entrenar)", "options": [{"name": "Bowl de yogur proteico y frutos rojos", "note": "Pon el yogur en un bol con los frutos rojos congelados y déjalos 5 min para que suelten jugo. Añade el muesli, la chía y el plátano en rodajas y termina con un hilo de crema de cacahuete.", "items": [{"n": "Yogur proteico Mercadona", "g": 220, "kcal": 114.4, "f": 1.1, "c": 8.14, "p": 22, "note": "Yogur +proteínas de Mercadona"}, {"n": "Frutos rojos congelados", "g": 100, "kcal": 45, "f": 0.4, "c": 8.5, "p": 0.9, "note": "Congelados, sin descongelar del todo"}, {"n": "Muesli 0% crunchy", "g": 55, "kcal": 220.6, "f": 6.6, "c": 28.6, "p": 4.84, "note": "Por encima, para que quede crujiente"}, {"n": "Chia", "g": 10, "kcal": 48.6, "f": 3.1, "c": 0.8, "p": 1.7, "note": "Por encima"}, {"n": "Platano", "g": 80, "kcal": 73.6, "f": 0.4, "c": 20.8, "p": 0.8, "note": "1 mediano, en rodajas"}, {"n": "Crema de cacahuetes 100%", "g": 10, "kcal": 60.8, "f": 4.7, "c": 1.2, "p": 3, "note": "Un hilo por encima"}]}, {"name": "Tostadas de aguacate, huevo y salmón", "note": "Tuesta el pan. Machaca el aguacate con limón y sal. Haz el huevo con las claras revueltas o a la plancha. Monta: aguacate, huevo y salmón ahumado por encima. Acompaña con el zumo.", "items": [{"n": "Pan integral", "g": 85, "kcal": 217.6, "f": 1.1, "c": 41.65, "p": 8.5, "note": "2-3 rebanadas, tostado"}, {"n": "Aguacate", "g": 30, "kcal": 48, "f": 4.41, "c": 4.56, "p": 0.6, "note": "Machacado con limón y sal"}, {"n": "Huevo M", "g": 55, "kcal": 78.7, "f": 5.5, "c": 0.55, "p": 6.82, "note": "1 huevo M a la plancha o poché"}, {"n": "Claras de huevo", "g": 80, "kcal": 33.6, "f": 0.4, "c": 0.4, "p": 8.8, "note": "Revueltas con el huevo"}, {"n": "Salmon ahumado", "g": 50, "kcal": 85.5, "f": 4.55, "c": 0.25, "p": 11, "note": "En láminas encima"}, {"n": "Zumo de naranja", "g": 200, "kcal": 94, "f": 3.2, "c": 20, "p": 4.8, "note": "1 vaso, o 1 naranja grande"}]}, {"name": "Overnight oats de frutos rojos", "note": "La noche anterior mezcla en un bote la avena, la leche, el yogur y la chía. Tapa y a la nevera. Por la mañana añade los frutos rojos por encima.", "items": [{"n": "Avena", "g": 70, "kcal": 268.8, "f": 4.97, "c": 41.93, "p": 8.54, "note": "Se prepara la noche anterior en un bote"}, {"n": "Leche +Proteinas mercadona", "g": 200, "kcal": 88, "f": 0.4, "c": 9.2, "p": 12}, {"n": "Yogur proteico Mercadona", "g": 125, "kcal": 65, "f": 0.62, "c": 4.62, "p": 12.5, "note": "Yogur proteico de Mercadona"}, {"n": "Chia", "g": 15, "kcal": 72.9, "f": 4.65, "c": 1.2, "p": 2.55}, {"n": "Frutos rojos congelados", "g": 120, "kcal": 5